// Zweck: Eingabe des Aufrufers pruefen und alle Pfade genau einmal bauen.
// Warum: bei ungueltiger Eingabe darf nichts in Nextcloud entstehen, der Aufrufer bekommt ok:false statt eines Absturzes.
// Warum ohne Binaerdaten: die Bilder holt 'Bilder bereitstellen' direkt vom Trigger, so tragen die Ordner-Knoten keine Binaerdaten mit.
const alle = $input.all();
const m = alle.length ? alle[0].json : {};
const t = function (s) { return String(s == null ? '' : s).trim(); };
const slug = function (s, max) {
  let x = t(s).toLowerCase();
  const umlaute = [[228, 'ae'], [246, 'oe'], [252, 'ue'], [223, 'ss']];
  for (const u of umlaute) { x = x.split(String.fromCharCode(u[0])).join(u[1]); }
  return x.replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, max).replace(/-+$/g, '');
};
const kunde = t(m.customer_code);
const postId = t(m.post_id);
// Warum ganze post_id: 8 Zeichen liessen abcdef12-1111 und abcdef12-2222 im selben Ordner landen.
// Warum eindeutige Kodierung: mit Pruefsumme nur bei bereinigten Kennungen kollidierten abc_def und abcdef-1me95v.
// Jetzt wird jedes Zeichen ausserhalb von A-Z, a-z, 0-9 und Bindestrich als _hex_ kodiert; '_' entsteht nur so, die Abbildung ist umkehrbar.
// Nur Kennungen ueber 40 Zeichen nach der Kodierung bekommen Anfang plus _x<Pruefsumme>_ (bei UUIDs mit 36 Zeichen nie).
// Diese Form ist immer genau 45 Zeichen lang und kann deshalb nie mit einer kurzen (hoechstens 40 Zeichen) gleich sein;
// zwei lange Kennungen kollidieren nur bei gleichem Anfang (35 Zeichen) und gleicher 32-Bit-Pruefsumme (bekannte Grenze).
const kodiert = Array.from(postId).map(ch => /[A-Za-z0-9-]/.test(ch) ? ch : '_' + ch.codePointAt(0).toString(16) + '_').join('');
const fnv = s => { let h = 2166136261; for (const ch of String(s)) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619); } return (h >>> 0).toString(36); };
const kurz = kodiert.length <= 40 ? kodiert : kodiert.slice(0, 35) + '_x' + fnv(postId).padStart(7, '0') + '_';
// Warum Startzeit: Ablage auswerten zaehlt nur Dateien, die in diesem Lauf geschrieben wurden.
const startIso = new Date().toISOString();
const thema = t(m.topic);
const trace = t(m.trace_id) || 'ohne-trace-id';
let grund = '';
if (!/^[A-Za-z0-9_-]{1,40}$/.test(kunde)) grund = 'customer_code fehlt oder enthaelt unerlaubte Zeichen';
else if (!kurz) grund = 'post_id fehlt';
else if (!thema) grund = 'topic fehlt';
let anzahl = 0;
for (const it of alle) {
  const f = t(it.json.file_name);
  if (!f) continue;
  anzahl++;
  // Warum Whitelist: der Dateiname wird Teil des Nextcloud-Pfads, Unterordner oder Punkte-Tricks sind nicht erlaubt.
  if (!grund && !/^[A-Za-z0-9_-]{1,60}[.](png|jpg|jpeg|webp)$/i.test(f)) grund = 'Dateiname ungueltig: ' + f.slice(0, 60);
}
if (grund) {
  return [{ json: { eingabe_ok: false, grund: grund, trace_id: trace, post_id: postId } }];
}
const datum = new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Berlin' });
const ordnerName = datum + '_' + kurz + '_' + (slug(thema, 40) || 'beitrag');
const wurzel = '/K1';
const kundeOrdner = wurzel + '/' + kunde;
const ordner = kundeOrdner + '/' + ordnerName;
let tags = m.hashtags;
if (Array.isArray(tags)) {
  tags = tags.map(function (x) { return String(x).trim(); }).filter(Boolean).map(function (x) { return x.startsWith('#') ? x : '#' + x; }).join(' ');
}
tags = t(tags);
const zeilen = ['# ' + thema, '', '- Kunde: ' + kunde, '- Beitrag: ' + postId, '- Thema: ' + thema, '- Datum: ' + datum, '- trace_id: ' + trace, '', '## Instagram-Text', '', t(m.caption_instagram), '', '## Hashtags', '', tags, '', '## LinkedIn-Text', '', t(m.linkedin_post), ''];
const text = zeilen.join(String.fromCharCode(10));
return alle.map(function (it) {
  const f = t(it.json.file_name);
  return { json: { eingabe_ok: true, start_iso: startIso, ordner: ordner, ordner_kunde: kundeOrdner, ordner_wurzel: wurzel, beitrag_pfad: ordner + '/beitrag.md', beitrag_text: text, bilder_anzahl: anzahl, trace_id: trace, post_id: postId, file_name: f, datei_pfad: f ? ordner + '/' + f : '' } };
});

// Zweck: jeden Fehlerweg (Eingabe, Ordner, Beitragstext, Bilder) in dieselbe Antwort ok:false verwandeln.
// Warum: der Aufrufer (Haupt-K1) soll nie abbrechen, er wertet nur das Feld ok aus.
const j = $input.first().json;
let plan = {};
try { plan = $('Eingabe prüfen und Pfade bauen [Code]').first().json || {}; } catch (e) { plan = {}; }
let grund = j.grund || '';
if (!grund && j.error) grund = typeof j.error === 'string' ? j.error : JSON.stringify(j.error);
if (!grund) grund = 'unbekannter Fehler';
return [{ json: { ok: false, ordner: j.ordner || plan.ordner || '', dateien: j.dateien || 0, grund: String(grund).slice(0, 300), trace_id: j.trace_id || plan.trace_id || '', post_id: j.post_id || plan.post_id || '' } }];

// Zweck: die Bild-Elemente MIT Binaerdaten wieder aufnehmen (Pfade aus der Pruefung, Binaerdaten direkt vom Trigger).
// Warum: ohne Bild bekommt der Upload-Knoten kein Element, deshalb ein Marker keine_bilder.
const plan = $('Eingabe prüfen und Pfade bauen [Code]').all();
const roh = $('Beitrag von der Haupt-K1 [Execute Workflow Trigger]').all();
const bilder = [];
plan.forEach(function (p, i) {
  if (!p.json.datei_pfad) return;
  const o = { json: p.json };
  if (roh[i] && roh[i].binary) o.binary = roh[i].binary;
  bilder.push(o);
});
if (!bilder.length) return [{ json: { keine_bilder: true } }];
return bilder;

// Zweck: den Erfolg der Ablage aus dem Ergebnis dieses Laufs bestimmen, nicht aus dem Ordnerinhalt allein.
// Warum ETag vorher und nachher: der Upload-Knoten meldet auch bei Erfolg einen internen TypeError
// (gemessen Lauf 1043), sein Ergebnis ist also kein Beleg. Nextcloud vergibt bei jedem Schreiben einen neuen ETag: eine Datei zaehlt nur,
// wenn sie vorher fehlte oder ihr ETag sich in diesem Lauf geaendert hat, und kein Upload-Element einen echten Fehler fuer sie meldet.
// Warum Set: zwei Elemente mit demselben Dateinamen zaehlen einmal.
const planAlle = $('Eingabe prüfen und Pfade bauen [Code]').all();
const plan = planAlle[0].json;
const name = p => String(p || '').split('/').pop();
let vorherFehler = false;
const vorher = {};
try {
  // Warum gebuendelt: die Liste kommt als 1 Element aus 'Vorherliste buendeln', der Text-Upload laeuft nur einmal.
  const b = $('Vorherliste bündeln [Code]').first().json;
  if (b.fehler) vorherFehler = true;
  for (const e of (b.dateien || [])) vorher[name(e.path)] = String(e.eTag || '');
} catch (e) { vorherFehler = true; }
const start = Date.parse(plan.start_iso || '') || 0;
const nachher = {};
for (const e of $input.all().map(i => i.json)) {
  if (e.type !== 'file' || !e.path) continue;
  nachher[name(e.path)] = { groesse: Number(e.contentLength || 0), etag: String(e.eTag || ''), zeit: Date.parse(e.lastModified || '') };
}
// Echte Upload-Fehler je Datei (der bekannte interne TypeError traegt kein Fehlerfeld am Element)
const uploadFehler = {};
try {
  for (const it of $('Ablage zusammenführen [Merge]').all()) {
    if (it.json.error && it.json.file_name) uploadFehler[it.json.file_name] = typeof it.json.error === 'string' ? it.json.error : JSON.stringify(it.json.error);
  }
} catch (e) { /* kein Bild im Lauf: Merge lief nicht, dann gibt es keine Bild-Uploadfehler */ }
const soll = Array.from(new Set(['beitrag.md'].concat(planAlle.map(p => p.json.file_name).filter(Boolean))));
const gruende = [];
for (const s of soll) {
  const n = nachher[s];
  if (!n || n.groesse <= 0) { gruende.push(s + ' fehlt'); continue; }
  if (uploadFehler[s]) { gruende.push(s + ' Upload-Fehler: ' + uploadFehler[s].slice(0, 120)); continue; }
  if (vorherFehler) {
    // Ohne Vorher-Liste nur Dateien, die nach dem Laufstart geschrieben wurden (5 s Spielraum fuer Uhrenabweichung)
    if (!(Number.isFinite(n.zeit) && n.zeit >= start - 5000)) gruende.push(s + ' nicht in diesem Lauf geschrieben');
    continue;
  }
  if (s in vorher && vorher[s] === n.etag) gruende.push(s + ' unveraendert (alte Fassung, Upload dieses Laufs nicht angekommen)');
}
const gut = gruende.length === 0;
return [{ json: { ablage_ok: gut, ordner: plan.ordner, dateien: soll.length - gruende.length, dateien_soll: soll.length, trace_id: plan.trace_id, post_id: plan.post_id,
  grund: gut ? '' : ('Nicht abgelegt: ' + gruende.join('; ')).slice(0, 300) } }];

// Zweck: aus der OCS-Antwort Freigabelink und Ablaufdatum lesen; jeder Fehler wird zu leerem Link plus Grund.
// Warum: die Ablage selbst darf nie scheitern, nur weil der Link fehlt (ok bleibt unberuehrt).
const j = $input.first().json || {};
const d = j.ocs && j.ocs.data ? j.ocs.data : null;
if (d && d.url) {
  return [{ json: { freigabe_link: String(d.url), freigabe_ablauf: String(d.expiration || '').slice(0, 10), grund_link: '' } }];
}
// Warum nur Code und Kurztext: der volle Fehlerblock waere unlesbar lang.
const e = j.error && typeof j.error === 'object' ? j.error : {};
let g = '';
if (e.httpCode || e.message) g = (e.httpCode ? 'HTTP ' + e.httpCode + ': ' : '') + String(e.message || '').slice(0, 120);
else if (typeof j.error === 'string') g = j.error.slice(0, 120);
else if (j.ocs && j.ocs.meta) g = 'OCS ' + j.ocs.meta.statuscode + ' ' + (j.ocs.meta.message || '');
else g = 'keine Link-Antwort von Nextcloud';
return [{ json: { freigabe_link: '', freigabe_ablauf: '', grund_link: 'Freigabelink: ' + g } }];

// Zweck: die Dateiliste vor dem Upload zu genau 1 Element buendeln.
// Warum: 'Ordner vorher auflisten' liefert 1 Element je Datei; ohne Buendelung bekaeme 'Beitragstext ablegen' N Elemente.
const alle = $input.all().map(i => i.json || {});
const fehler = alle.some(j => j.error);
const dateien = alle.filter(j => j.type === 'file' && j.path).map(j => ({ path: j.path, eTag: j.eTag || '' }));
return [{ json: { fehler, dateien, anzahl: dateien.length } }];
